n=30
g=[[0]*n for _ in range(n)]
starts=[1,8,15,22,29]
# Tile frames, including cropped edge tiles
for r0 in starts:
 for c0 in starts:
  for r in range(r0,min(r0+5,n)):
   for c in range(c0,min(c0+5,n)):
    if r in (r0,r0+4) or c in (c0,c0+4): g[r][c]=4
colors=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
for i in range(4):
 for j in range(4):
  for r in range(3):
   for c in range(3): g[starts[i]+1+r][starts[j]+1+c]=colors[i][j]
# Draw connectors for non-background colors between aligned repeated patches, only in blank tile gaps.
# Horizontal: color 3 across outer columns in tile rows 0,2; color 8 between central columns in rows 1,3.
for i in (0,2):
 for r in range(starts[i]+1,starts[i]+4):
  for c in (6,7,13,14,20,21): g[r][c]=3
for i in (1,3):
 for r in range(starts[i]+1,starts[i]+4):
  for c in (13,14): g[r][c]=8
# Vertical: analogous aligned columns.
for j in (0,3):
 for c in range(starts[j]+1,starts[j]+4):
  for r in (6,7,13,14): g[r][c]=3
for j in (1,2):
 for c in range(starts[j]+1,starts[j]+4):
  for r in (13,14): g[r][c]=8
print('\n'.join(' '.join(map(str,row)) for row in g))

